-- ============================================================================
-- Smart Parking Management & Usage Analysis System (SPMS)
-- Database: PostgreSQL Schema & Complete Seed Data
-- Prepared for DBMS Lab Evaluation & Academic Viva
-- ============================================================================

-- Step 1: Create and connect to database (run in psql or create via pgAdmin GUI)
-- CREATE DATABASE smart_parking_db;
-- \c smart_parking_db;

DROP TABLE IF EXISTS parking_history CASCADE;
DROP TABLE IF EXISTS parked_vehicles CASCADE;
DROP TABLE IF EXISTS slots CASCADE;
DROP TABLE IF EXISTS areas CASCADE;

-- ============================================================================
-- 1. TABLE: areas (Campus parking facilities & wings)
-- ============================================================================
CREATE TABLE areas (
    id VARCHAR(20) PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    location VARCHAR(150) NOT NULL,
    capacity INTEGER NOT NULL CHECK (capacity > 0),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- ============================================================================
-- 2. TABLE: slots (Individual parking slots per area)
-- ============================================================================
CREATE TABLE slots (
    id VARCHAR(30) PRIMARY KEY,
    slot_number VARCHAR(20) NOT NULL UNIQUE,
    area_id VARCHAR(20) NOT NULL,
    slot_type VARCHAR(20) NOT NULL CHECK (slot_type IN ('Car', 'Bike', 'Truck')),
    is_occupied BOOLEAN NOT NULL DEFAULT FALSE,
    current_vehicle_no VARCHAR(20),
    CONSTRAINT fk_slots_area FOREIGN KEY (area_id) REFERENCES areas(id) ON DELETE CASCADE
);

-- ============================================================================
-- 3. TABLE: parked_vehicles (Active live parking records)
-- ============================================================================
CREATE TABLE parked_vehicles (
    ticket_id VARCHAR(50) PRIMARY KEY,
    vehicle_no VARCHAR(20) NOT NULL UNIQUE,
    vehicle_type VARCHAR(20) NOT NULL CHECK (vehicle_type IN ('Car', 'Bike', 'Truck')),
    owner_name VARCHAR(100) NOT NULL,
    contact_number VARCHAR(15) NOT NULL,
    area_id VARCHAR(20) NOT NULL,
    area_name VARCHAR(100) NOT NULL,
    slot_number VARCHAR(20) NOT NULL,
    entry_time TIMESTAMP NOT NULL,
    rate_per_hour NUMERIC(8,2) NOT NULL CHECK (rate_per_hour > 0),
    CONSTRAINT fk_parked_area FOREIGN KEY (area_id) REFERENCES areas(id)
);

-- ============================================================================
-- 4. TABLE: parking_history (Historical completed billing transactions)
-- ============================================================================
CREATE TABLE parking_history (
    ticket_id VARCHAR(50) PRIMARY KEY,
    vehicle_no VARCHAR(20) NOT NULL,
    vehicle_type VARCHAR(20) NOT NULL CHECK (vehicle_type IN ('Car', 'Bike', 'Truck')),
    owner_name VARCHAR(100) NOT NULL,
    contact_number VARCHAR(15) NOT NULL,
    area_id VARCHAR(20) NOT NULL,
    area_name VARCHAR(100) NOT NULL,
    slot_number VARCHAR(20) NOT NULL,
    entry_time TIMESTAMP NOT NULL,
    exit_time TIMESTAMP NOT NULL,
    duration_hours NUMERIC(6,2) NOT NULL,
    billed_hours INTEGER NOT NULL CHECK (billed_hours >= 1),
    rate_per_hour NUMERIC(8,2) NOT NULL,
    total_fee NUMERIC(10,2) NOT NULL CHECK (total_fee >= 0),
    payment_method VARCHAR(30) NOT NULL DEFAULT 'CASH',
    status VARCHAR(20) NOT NULL DEFAULT 'COMPLETED',
    CONSTRAINT fk_history_area FOREIGN KEY (area_id) REFERENCES areas(id)
);

